export function getT3Ending(score) {
  const max = 100 + 32 * 15; // 580
  const pct = score / max;
  if (pct >= 0.85) return { title: 'UI Architect', summary: 'You see components as contracts, states as communication, and patterns as a shared language. Your UI doesn\'t just look right — it works right, for everyone.' };
  if (pct >= 0.65) return { title: 'Component Craftsperson', summary: 'You build components that other designers and developers trust. You know the difference between a button that works and a button that communicates.' };
  if (pct >= 0.45) return { title: 'Pattern Learner', summary: 'You\'re developing strong UI intuitions. The gap is in the details — states, accessibility, and the edge cases that matter most when things go wrong.' };
  return { title: 'UI Foundations Needed', summary: 'Good UI craft is learnable. Focus on the states designers forget (error, loading, empty, disabled) and the accessibility requirements that protect all users.' };
}
